<?php declare(strict_types=1);require_once __DIR__.'/../config/auth.php';page_require(['ADMIN','VERIFICADOR']);?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Alertas — Franky</title><style>*{box-sizing:border-box}body{margin:0;background:#f4f7fb;color:#172033;font-family:Manrope,Arial,sans-serif}.wrap{max-width:900px;margin:auto;padding:82px 14px 32px}h1{margin:0;font-size:30px}.sub{color:#64748b;margin:6px 0 18px}.list{display:grid;gap:10px}.a{display:block;text-decoration:none;color:inherit;background:#fff;border:1px solid #e5eaf0;border-radius:16px;padding:15px;box-shadow:0 5px 18px #0f172a0d}.top{display:flex;justify-content:space-between;gap:10px}.tag{font-size:10px;font-weight:900;letter-spacing:.06em;text-transform:uppercase;padding:5px 8px;border-radius:999px;background:#eef2f7}.tit{font-size:16px;font-weight:900;margin-top:8px}.det{font-size:13px;color:#64748b;margin-top:5px;line-height:1.5}.ALTA{border-left:5px solid #dc2626}.MEDIA{border-left:5px solid #f59e0b}.BAJA{border-left:5px solid #2563eb}.OK{border-left:5px solid #16a34a}.empty{background:#fff;border-radius:16px;padding:26px;text-align:center;color:#64748b}</style></head><body><main class="wrap"><h1>Centro de alertas</h1><div class="sub">Lo que requiere atención operativa ahora mismo.</div><div id="list" class="list"><div class="empty">Cargando…</div></div></main><script>const l=document.getElementById('list'),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));fetch('/api/alertas.php').then(r=>r.json()).then(d=>{if(!d.ok)throw Error(d.error||'Error');l.innerHTML=d.alertas.length?d.alertas.map(x=>`<a class="a ${x.nivel}" href="${esc(x.href)}"><div class="top"><span class="tag">${esc(x.tipo)}</span><span>›</span></div><div class="tit">${esc(x.titulo)}</div><div class="det">${esc(x.detalle)}</div></a>`).join(''):'<div class="empty">Todo tranquilo por ahora ✓</div>'}).catch(e=>l.innerHTML=`<div class="empty">${esc(e.message)}</div>`)</script></body></html>